import { test, expect } from '@playwright/test';

test.describe('Email Field Inline Validation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/contact-form');
  });

  test('should display inline validation error when email format is invalid', async ({ page }) => {
    // Locate and fill email field using getByLabel
    const emailInput = page.getByLabel('Email Address');
    await emailInput.fill('invalid-email');

    // Wait for validation to trigger
    await page.waitForTimeout(500);

    // Verify error message appears using getByRole
    const errorMessage = page.getByRole('alert');
    await expect(errorMessage).toBeVisible();
    await expect(errorMessage).toContainText('Please enter a valid email address');

    // Verify error styling is applied
    await expect(emailInput).toHaveClass(/error-border/);

    // Verify submit button is disabled
    const submitButton = page.getByRole('button', { name: 'Submit' });
    await expect(submitButton).toBeDisabled();
  });

  test('should clear inline validation error when email format becomes valid', async ({ page }) => {
    // Locate and fill email field with invalid format
    const emailInput = page.getByLabel('Email Address');
    await emailInput.fill('invalid-email');

    // Wait for initial validation error
    await page.waitForTimeout(500);

    // Verify error message is visible
    const errorMessage = page.getByRole('alert');
    await expect(errorMessage).toBeVisible();

    // Correct the email format
    await emailInput.fill('user@example.com');

    // Wait for validation to clear
    await page.waitForTimeout(500);

    // Verify error message is no longer visible
    await expect(errorMessage).not.toBeVisible();

    // Verify error styling is removed
    await expect(emailInput).not.toHaveClass(/error-border/);

    // Verify submit button is enabled
    const submitButton = page.getByRole('button', { name: 'Submit' });
    await expect(submitButton).not.toBeDisabled();
  });
});
